(548, 32, 36, 'La luz hace que la cobertura se vea todavía más brillante. Fotón.', '2026-08-26 10:05:37', '2026-08-26 10:05:37'),
(549, 36, 36, 'Esa cobertura parece pintada a mano, ha quedado preciosa 🎨', '2026-08-26 10:44:09', '2026-08-26 10:44:09'),
(550, 41, 36, 'La miga se ve húmeda y compacta, justo como debería quedar una buena tarta de chocolate.', '2026-08-26 11:20:12', '2026-08-26 11:20:12'),
(551, 41, 36, '¿Dejaste reposar la ganache antes de extenderla? El acabado está perfecto.', '2026-08-26 11:21:03', '2026-08-26 11:21:03'),
(552, 21, 36, '¡Sí! La dejé reposar unos minutos para que cogiera cuerpo sin endurecerse 😊', '2026-08-26 11:31:26', '2026-08-26 11:31:26'),
(553, 28, 36, 'Qué buena estructura tiene el bizcocho. Se nota jugoso incluso en la foto.', '2026-08-26 12:02:15', '2026-08-26 12:02:15'),
