(558, 42, 36, 'La acompañaría con una película larga y una manta. Plan perfecto 🎬', '2026-08-26 14:25:54', '2026-08-26 14:25:54'),
(559, 39, 36, 'Un trozo de esta tarta y un vinilo sonando de fondo. Firmo ahora mismo.', '2026-08-26 15:12:11', '2026-08-26 15:12:11'),
(560, 40, 36, 'No sé mucho de repostería, pero sí sé que necesito probarla.', '2026-08-26 16:05:33', '2026-08-26 16:05:33'),
(561, 44, 36, 'Nala no puede probarla, así que tendré que comerme su porción también 🐾', '2026-08-26 17:20:07', '2026-08-26 17:20:07'),
(562, 38, 36, 'El acabado brillante de la cobertura le da un aspecto increíble.', '2026-08-26 18:12:46', '2026-08-26 18:12:46'),
