--
-- Estructura de tabla para la tabla `images`
--

DROP TABLE IF EXISTS `images`;
CREATE TABLE IF NOT EXISTS `images` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint UNSIGNED DEFAULT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `original_name` varchar(255) DEFAULT NULL,
  `description` text,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_images_users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=203 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Volcado de datos para la tabla `images`
--

INSERT INTO `images` (`id`, `user_id`, `image_path`, `original_name`, `description`, `created_at`, `updated_at`) VALUES
(2, 20, '6a8b30193d8d5_1787506713.jpg', '6a8b30193d8d5_1787506713.png', 'Un rato de calma, café caliente y unas páginas antes de empezar el día. A veces no hace falta salir de casa para disfrutar de un buen momento.', '2026-04-05 13:21:00', '2026-08-26 10:40:21'),
(3, 20, '6a8b3ff8473c8_1787510776.jpg', '6a8b3ff8473c8_1787510776.png', '📍 Naxos, Grecia\nPescado fresco frente al puerto, con el sonido de los barcos de fondo. Una comida sencilla y perfecta para recordar el viaje.', '2024-04-18 12:07:00', '2026-08-26 10:40:21'),
(4, 20, '6a8b3ffead4f2_1787510782.jpg', '6a8b3ffead4f2_1787510782.png', '📍 Roma, Italia\nPasta recién hecha, una mesa pequeña y todo el tiempo del mundo para disfrutarla. Así da gusto descubrir una ciudad.', '2024-12-29 10:11:00', '2026-08-26 10:40:21'),
(5, 20, '6a8b4005e81aa_1787510789.jpg', '6a8b4005e81aa_1787510789.png', '📍 Merzouga, Marruecos\nCaminar entre dunas al final de la tarde fue una de esas experiencias que te hacen sentir muy pequeña frente al paisaje.', '2023-10-29 13:27:00', '2026-08-26 10:40:21'),
(6, 20, '6a8b400c42a72_1787510796.jpg', '6a8b400c42a72_1787510796.png', '📍 Costa sur de Islandia\nViento, arena negra y una cascada enorme detrás. Compartir esta ruta con ellos hizo que el día fuera todavía más especial.', '2024-07-21 17:58:00', '2026-08-26 10:40:21'),
(7, 20, '6a8b4013ad557_1787510803.jpg', '6a8b4013ad557_1787510803.png', '📍 Procida, Italia\nUn café junto al puerto, casas de colores y una conversación que se alargó hasta que empezó a caer el sol.', '2023-10-06 14:18:00', '2026-08-26 10:40:21'),
(8, 20, '6a8b401a347e1_1787510810.jpg', '6a8b401a347e1_1787510810.png', '📍 Oporto, Portugal\nLa ciudad encendiéndose poco a poco mientras nosotros buscábamos el mejor rincón para guardar este recuerdo.', '2025-08-17 18:31:00', '2026-08-26 10:40:21'),
(9, 20, '6a8b40204249f_1787510816.jpg', '6a8b40204249f_1787510816.png', '📍 Parque Nacional de Banff, Canadá\nUna subida que costó lo suyo, pero con unas vistas que hicieron que cada paso mereciera la pena.', '2024-02-08 20:16:00', '2026-08-26 10:40:21'),
(10, 20, '6a8b40272bff9_1787510823.jpg', '6a8b40272bff9_1787510823.png', '📍 Fiordo de Geiranger, Noruega\nMontañas, agua y silencio hasta donde alcanza la vista. Uno de esos lugares que parecen irreales incluso cuando estás allí.', '2024-10-27 19:02:00', '2026-08-26 10:40:21'),
(11, 20, '6a8b402d4b36f_1787510829.jpg', '6a8b402d4b36f_1787510829.png', '📍 Fiordo de Geiranger, Noruega\nCruzar el fiordo en barco, con el aire frío en la cara y pequeñas casas apareciendo entre las montañas.', '2023-09-17 10:42:00', '2026-08-26 10:40:21'),
(12, 20, '6a8b40352b0ab_1787510837.jpg', '6a8b40352b0ab_1787510837.png', '📍 Real Jardín Botánico, Madrid\nUna mañana entre plantas enormes, humedad y ese olor a tierra mojada que siempre invita a caminar más despacio.', '2024-06-02 11:23:00', '2026-08-26 10:40:21'),
(13, 20, '6a8b403b137e3_1787510843.jpg', '6a8b403b137e3_1787510843.png', '📍 Fiordo de Geiranger, Noruega\nOtro momento del trayecto en barco. No podía dejar de mirar cómo las montañas se perdían al fondo del fiordo.', '2025-06-22 17:47:00', '2026-08-26 10:40:21'),
(14, 20, '6a8b404329424_1787510851.jpg', '6a8b404329424_1787510851.png', 'Tarde tranquila en casa, sin planes y sin prisa. Justo lo que necesitaba después de una semana intensa.', '2023-11-21 17:06:00', '2026-08-26 10:40:21'),
(15, 20, '6a8b404b5d21e_1787510859.jpg', '6a8b404b5d21e_1787510859.png', 'Café caliente, lluvia al otro lado de la ventana y un rato para desconectar de todo.', '2025-03-29 19:14:00', '2026-08-26 10:40:21'),
(16, 20, '6a8b405cd1f48_1787510876.jpg', '6a8b405cd1f48_1787510876.png', '📍 Jardín Kenroku-en, Kanazawa\nEl otoño había llenado cada rincón de color. Caminar por este jardín bajo una lluvia fina fue pura calma.', '2025-11-08 10:33:00', '2026-08-26 10:40:21'),
(17, 20, '6a8b447f1c78d_1787511935.jpg', '6a8b447f1c78d_1787511935.png', '📍 En casa\nNoche de pizza casera desde cero. Preparar la masa con calma sigue siendo mi parte favorita.', '2024-10-06 13:15:00', '2026-08-26 10:40:21'),
(18, 20, '6a8b4487a2139_1787511943.jpg', '6a8b4487a2139_1787511943.png', '📍 En casa\nUn plato caliente hecho con verduras, garbanzos y mucho cariño. Comida sencilla de la que siempre apetece repetir.', '2025-07-19 11:09:00', '2026-08-26 10:40:21'),
(19, 20, '6a8b44901dafa_1787511952.jpg', '6a8b44901dafa_1787511952.png', '📍 Parque Nacional de Oulanka, Finlandia\nEl bosque completamente nevado y el río abriéndose paso entre el hielo. El frío se olvida cuando el paisaje es así.', '2024-11-20 13:38:00', '2026-08-26 10:40:21'),
(20, 20, '6a8b449b8bf81_1787511963.jpg', '6a8b449b8bf81_1787511963.png', '📍 Monteverde, Costa Rica\nCruzando el bosque nuboso entre niebla, hojas gigantes y el sonido del agua bajo el puente.', '2025-09-20 07:42:00', '2026-08-26 10:40:21'),
(21, 20, '6a8b44a2e966a_1787511970.jpg', '6a8b44a2e966a_1787511970.png', '📍 Gante, Bélgica\nLa lluvia dejó las calles brillando justo cuando empezaban a encenderse las luces de la ciudad. Una tarde preciosa para perderse sin mapa.', '2026-08-18 22:09:00', '2026-08-26 10:40:21'),
(22, 20, '6a8b44a9828fa_1787511977.jpg', '6a8b44a9828fa_1787511977.png', '📍 Patagonia argentina\nUna mañana entre hielo, agua y los vecinos más curiosos del viaje. Difícil olvidar un encuentro así.', '2025-02-15 08:56:00', '2026-08-26 10:40:21'),
(23, 20, '6a8b44b2e1b3a_1787511986.jpg', '6a8b44b2e1b3a_1787511986.png', '📍 Deadvlei, Namibia\nDunas rojas, árboles inmóviles y un silencio absoluto. El paisaje más extraño y fascinante que he pisado.', '2025-05-11 10:26:00', '2026-08-26 10:40:21'),
(24, 20, '6a8b44c6833b6_1787512006.jpg', '6a8b44c6833b6_1787512006.png', '📍 Lagos de Plitvice, Croacia\nPasarelas de madera, agua turquesa y cascadas escondidas entre los árboles. Un lugar para recorrer sin mirar el reloj.', '2026-02-21 12:48:00', '2026-08-26 10:40:21'),
(25, 20, '6a8b44d06437d_1787512016.jpg', '6a8b44d06437d_1787512016.png', '📍 Salar de Uyuni, Bolivia\nEl cielo y la tierra mezclándose en el horizonte. Caminar aquí se siente como hacerlo sobre otro mundo.', '2024-05-09 15:41:00', '2026-08-26 10:40:21'),
(26, 20, '6a8b44e28e72c_1787512034.jpg', '6a8b44e28e72c_1787512034.png', '📍 Capadocia, Turquía\nVer amanecer desde un globo, rodeada de decenas más y con todo el valle bajo los pies. Una experiencia inolvidable.', '2024-08-13 09:44:00', '2026-08-26 10:40:21'),
(27, 20, '6a8b44e90749c_1787512041.jpg', '6a8b44e90749c_1787512041.png', '📍 Mercado nocturno de Taipéi, Taiwán\nProbando uno de esos bocados callejeros que huelen demasiado bien como para pasar de largo.', '2025-10-18 21:05:00', '2026-08-26 10:40:21'),
(28, 20, '6a8b44f3648aa_1787512051.jpg', '6a8b44f3648aa_1787512051.png', '📍 Takayama, Japón\nEsperando el tren en una estación pequeña, rodeada de montañas y con la lluvia marcando el ritmo del viaje.', '2024-03-03 09:52:00', '2026-08-26 10:40:21'),
(29, 20, '6a8b4506d691d_1787512070.jpg', '6a8b4506d691d_1787512070.png', '📍 Kioto, Japón\nMi primera clase de cerámica. Las manos acabaron llenas de barro, pero conseguí una pieza que me llevé a casa con muchísimo cariño.', '2026-06-28 14:37:00', '2026-08-26 10:40:21'),
(30, 20, '6a8b451678836_1787512086.jpg', '6a8b451678836_1787512086.png', '📍 Ámsterdam, Países Bajos\nCanales, bicicletas y calles mojadas. La mejor forma de conocer la ciudad fue recorrerla sin un rumbo fijo.', '2025-12-13 16:12:00', '2026-08-26 10:40:21'),
(31, 20, '6a8b452038f40_1787512096.jpg', '6a8b452038f40_1787512096.png', '📍 Roma, Italia\nUna parada para comer pasta después de toda la mañana caminando. No quedó absolutamente nada en el plato.', '2024-06-28 16:36:00', '2026-08-26 10:40:21'),
(32, 20, '6a8b452764cff_1787512103.jpg', '6a8b452764cff_1787512103.png', '📍 Naxos, Grecia\nComer junto al puerto con pescado recién hecho y vistas a los barcos. Uno de esos pequeños lujos que regala el viaje.', '2026-07-24 14:37:00', '2026-08-26 10:40:21'),
(33, 20, '6a8b453506724_1787512117.jpg', '6a8b453506724_1787512117.png', '📍 Nueva York, Estados Unidos\nUna cena especial con la ciudad iluminada al otro lado del cristal. El cierre perfecto para un viaje que no quería que terminara.', '2025-09-02 22:09:00', '2026-08-26 10:40:21'),
(34, 21, '6a8c1ef363117_1787567859.jpg', '6a8c1ef363117_1787567859.png', '🍽️ Curry de garbanzos y espinacas\n\nUn curry cremoso, aromático y reconfortante, acompañado de arroz blanco para aprovechar hasta la última cucharada.\n\n📜 Ingredientes:\n● 400 g de garbanzos cocidos\n● 200 g de espinacas frescas\n● 400 g de tomate triturado\n● 1 cebolla mediana\n● 2 dientes de ajo\n● 250 ml de leche de coco\n● 1 cucharada de curry\n● 1/2 cucharadita de comino\n● 1/2 cucharadita de cúrcuma\n● 200 g de arroz basmati\n● Aceite de oliva y sal\n\n🥣 Procedimiento:\n● Lava el arroz hasta que el agua salga clara y cuécelo siguiendo el tiempo indicado en el paquete.\n● Pica la cebolla y el ajo y sofríelos con aceite durante 8 minutos, hasta que estén tiernos.\n● Añade el curry, el comino y la cúrcuma y remueve durante 30 segundos para potenciar su aroma.\n● Incorpora el tomate triturado y cocina 8 minutos a fuego medio, removiendo de vez en cuando.\n● Agrega los garbanzos escurridos y la leche de coco y cocina todo a fuego suave durante 15 minutos.\n● Añade las espinacas, mezcla hasta que se ablanden, ajusta de sal y sirve el curry junto al arroz.', '2026-07-11 14:15:00', '2026-08-26 10:40:21'),
(35, 21, '6a8c1efb15da9_1787567867.jpg', '6a8c1efb15da9_1787567867.png', '🍽️ Ramen de cerdo y huevo\n\nUn bol de ramen casero con caldo sabroso, cerdo tierno, setas y huevo de yema cremosa.\n\n📜 Ingredientes:\n● 300 g de fideos ramen\n● 1 litro de caldo de pollo\n● 300 g de panceta o lomo de cerdo\n● 2 huevos\n● 150 g de setas\n● 3 cucharadas de salsa de soja\n● 1 diente de ajo\n● 2 cm de jengibre fresco\n● 1 cebolleta\n● 1 cucharadita de aceite de sésamo\n\n🥣 Procedimiento:\n● Cuece los huevos durante 7 minutos, pásalos a agua con hielo, pélalos y córtalos por la mitad.\n● Corta el cerdo en porciones y dóralo en una sartén hasta que quede bien sellado por ambos lados.\n● Calienta el caldo con el ajo, el jengibre, la salsa de soja y el aceite de sésamo durante 10 minutos.\n● Añade las setas laminadas al caldo y cocínalas durante 5 minutos para que aporten todo su sabor.\n● Cuece los fideos aparte, escúrrelos bien y repártelos entre los boles.\n● Vierte el caldo caliente y termina con el cerdo, el huevo y la cebolleta cortada muy fina.', '2026-05-02 10:20:00', '2026-08-26 10:40:21'),
(36, 21, '6a8c1f03aecc9_1787567875.jpg', '6a8c1f03aecc9_1787567875.png', '🍽️ Tarta de chocolate\n\nUna tarta intensa y jugosa, cubierta con una crema de chocolate suave y brillante.\n\n📜 Ingredientes:\n● 200 g de harina de trigo\n● 60 g de cacao puro\n● 180 g de azúcar\n● 3 huevos\n● 180 ml de leche\n● 100 ml de aceite suave\n● 12 g de levadura química\n● 200 g de chocolate negro\n● 200 ml de nata para montar\n● 1 pizca de sal\n\n🥣 Procedimiento:\n● Precalienta el horno a 180 °C y forra la base de un molde con papel de horno.\n● Tamiza la harina, el cacao, la levadura y la sal y mézclalos con el azúcar.\n● Incorpora los huevos, la leche y el aceite y bate solo hasta obtener una masa homogénea.\n● Vierte la masa en el molde y hornea durante 35 minutos; comprueba el centro con un palillo.\n● Deja reposar 10 minutos, desmolda y espera a que el bizcocho se enfríe por completo.\n● Calienta la nata sin que hierva, viértela sobre el chocolate, mezcla hasta que quede lisa y cubre la tarta.', '2026-08-22 17:45:00', '2026-08-26 10:40:21'),
(37, 21, '6a8c1f0c10e9d_1787567884.jpg', '6a8c1f0c10e9d_1787567884.png', '🍽️ Tortitas con fruta\n\nTortitas esponjosas servidas con fruta fresca, yogur y un toque de miel para un desayuno especial.\n\n📜 Ingredientes:\n● 180 g de harina de trigo\n● 250 ml de leche\n● 1 huevo\n● 25 g de azúcar\n● 8 g de levadura química\n● 20 g de mantequilla\n● 125 g de yogur natural\n● 1 plátano\n● 6 fresas\n● 50 g de arándanos\n● Miel al gusto\n\n🥣 Procedimiento:\n● Mezcla la harina, el azúcar y la levadura en un bol amplio.\n● Bate el huevo con la leche y viértelo poco a poco sobre los ingredientes secos.\n● Remueve hasta que no queden grumos grandes y deja reposar la masa durante 10 minutos.\n● Engrasa una sartén con un poco de mantequilla y caliéntala a fuego medio.\n● Cocina pequeñas porciones y dales la vuelta cuando aparezcan burbujas en la superficie.\n● Apila las tortitas y añade el yogur, la fruta cortada y un hilo de miel justo antes de servir.', '2026-08-01 12:40:00', '2026-08-26 10:40:21'),
(38, 21, '6a8c201aa4817_1787568154.jpg', '6a8c201aa4817_1787568154.png', '🍽️ Paella de marisco\n\nArroz lleno de sabor a mar, con marisco variado y el punto tostado que convierte cada ración en una fiesta.\n\n📜 Ingredientes:\n● 320 g de arroz redondo\n● 900 ml de caldo de pescado caliente\n● 8 gambas\n● 500 g de mejillones\n● 250 g de calamar\n● 2 tomates maduros rallados\n● 1/2 pimiento rojo\n● 2 dientes de ajo\n● 1 cucharadita de pimentón\n● Unas hebras de azafrán\n● Aceite de oliva, sal y limón\n\n🥣 Procedimiento:\n● Limpia el marisco, abre los mejillones al vapor y reserva también el líquido que hayan soltado.\n● Dora las gambas y el calamar en la paellera con aceite y retíralos para evitar que se cocinen de más.\n● Sofríe el pimiento y el ajo, añade el tomate rallado y cocina hasta que pierda toda el agua.\n● Incorpora el pimentón, el azafrán y el arroz y remueve durante un minuto para nacararlo.\n● Vierte el caldo caliente y cocina 8 minutos a fuego fuerte y otros 10 a fuego medio sin remover.\n● Coloca el marisco encima durante los últimos minutos, apaga el fuego y deja reposar 5 minutos antes de servir.', '2026-07-25 20:10:00', '2026-08-26 10:40:21'),
(39, 21, '6a8c20265b9d4_1787568166.jpg', '6a8c20265b9d4_1787568166.png', '🍽️ Espaguetis a la carbonara\n\nUna carbonara cremosa sin nata, con queso, pimienta negra y guanciale bien dorado.\n\n📜 Ingredientes:\n● 320 g de espaguetis\n● 180 g de guanciale o panceta\n● 3 yemas de huevo\n● 1 huevo entero\n● 90 g de queso pecorino o parmesano\n● Pimienta negra recién molida\n● Sal para cocer la pasta\n\n🥣 Procedimiento:\n● Corta el guanciale en tiras y cocínalo a fuego medio, sin añadir aceite, hasta que quede dorado.\n● Bate las yemas y el huevo con el queso rallado y abundante pimienta hasta formar una crema espesa.\n● Cuece los espaguetis en agua con poca sal y reserva un vaso del agua de cocción antes de escurrirlos.\n● Añade la pasta a la sartén del guanciale, mezcla bien y retírala completamente del fuego.\n● Incorpora la crema de huevo y queso mientras remueves con rapidez para que no se cuaje.\n● Ajusta la textura con pequeñas cantidades de agua de cocción y sirve inmediatamente con más queso y pimienta.', '2026-05-16 13:40:00', '2026-08-26 10:40:21'),
(40, 21, '6a8c202d53acd_1787568173.jpg', '6a8c202d53acd_1787568173.png', '🍽️ Hamburguesa casera con patatas\n\nUna hamburguesa jugosa con queso fundido, verduras frescas y patatas doradas al horno.\n\n📜 Ingredientes:\n● 400 g de carne picada de ternera\n● 2 panes de hamburguesa\n● 2 lonchas de queso\n● 2 hojas de lechuga\n● 1 tomate\n● 1/2 cebolla morada\n● 500 g de patatas\n● 2 cucharadas de aceite de oliva\n● Sal y pimienta\n● Salsa al gusto\n\n🥣 Procedimiento:\n● Precalienta el horno a 210 °C y corta las patatas en gajos del mismo tamaño.\n● Mezcla las patatas con aceite, sal y pimienta y hornéalas durante 35 minutos, dándoles la vuelta a mitad.\n● Divide la carne en dos porciones, forma las hamburguesas sin prensarlas demasiado y sazónalas justo antes de cocinarlas.\n● Cocina las hamburguesas en una plancha muy caliente y coloca el queso encima durante el último minuto.\n● Abre los panes y tuéstalos ligeramente para que no se humedezcan con los jugos.\n● Monta cada hamburguesa con salsa, lechuga, tomate, cebolla y carne y sírvela con las patatas.', '2026-06-06 13:05:00', '2026-08-26 10:40:21'),
(41, 21, '6a8c2034bdfca_1787568180.jpg', '6a8c2034bdfca_1787568180.png', '🍽️ Tacos de ternera y aguacate\n\nTacos llenos de sabor, con ternera especiada, aguacate cremoso, cebolla y un toque fresco de lima.\n\n📜 Ingredientes:\n● 8 tortillas de maíz\n● 400 g de carne picada de ternera\n● 1 aguacate maduro\n● 1/2 cebolla morada\n● 1 tomate\n● 1 lima\n● 1 cucharadita de comino\n● 1 cucharadita de pimentón\n● Chile al gusto\n● Cilantro fresco\n● Aceite y sal\n\n🥣 Procedimiento:\n● Pica la cebolla y el tomate, corta el aguacate en dados y riégalo con un poco de lima.\n● Calienta una sartén con aceite y dora la carne a fuego fuerte, separándola con una cuchara.\n● Añade el comino, el pimentón, el chile y la sal y cocina 3 minutos más para integrar los sabores.\n● Calienta las tortillas unos segundos por cada lado hasta que estén flexibles y ligeramente tostadas.\n● Reparte la carne entre las tortillas y añade el aguacate, la cebolla y el tomate.\n● Termina con cilantro fresco y unas gotas de lima y sirve los tacos recién montados.', '2026-08-15 21:00:00', '2026-08-26 10:40:21'),
(42, 21, '6a8c203d91d67_1787568189.jpg', '6a8c203d91d67_1787568189.png', '🍽️ Tortilla de patatas\n\nLa receta clásica de siempre: dorada por fuera, tierna por dentro y perfecta para compartir.\n\n📜 Ingredientes:\n● 700 g de patatas\n● 6 huevos\n● 1 cebolla grande\n● 300 ml de aceite de oliva\n● Sal al gusto\n\n🥣 Procedimiento:\n● Pela las patatas, córtalas en láminas finas y pica la cebolla en tiras pequeñas.\n● Calienta el aceite a fuego medio y cocina las patatas y la cebolla lentamente durante unos 25 minutos.\n● Retira la mezcla cuando esté tierna, escúrrela muy bien y deja que pierda un poco de temperatura.\n● Bate los huevos con sal, incorpora las patatas y deja reposar la mezcla durante 5 minutos.\n● Vierte todo en una sartén antiadherente con una cucharada de aceite y cuaja la primera cara.\n● Dale la vuelta con un plato, cocina la otra cara al punto deseado y deja reposar unos minutos antes de cortarla.', '2026-04-11 13:15:00', '2026-08-26 10:40:21'),
(43, 21, '6a8c20446a5e2_1787568196.jpg', '6a8c20446a5e2_1787568196.png', '🍽️ Salmón al horno con verduras\n\nUn plato completo y sencillo con salmón jugoso, patatas tiernas y verduras asadas.\n\n📜 Ingredientes:\n● 2 lomos de salmón\n● 400 g de patatas pequeñas\n● 200 g de espárragos verdes\n● 200 g de tomates cherry\n● 1 limón\n● 2 dientes de ajo\n● 3 cucharadas de aceite de oliva\n● Romero o eneldo\n● Sal y pimienta\n\n🥣 Procedimiento:\n● Precalienta el horno a 200 °C y corta las patatas en mitades para que se cocinen de manera uniforme.\n● Coloca las patatas en una fuente, añade aceite, sal y pimienta y hornéalas durante 25 minutos.\n● Incorpora los espárragos y los tomates y mezcla las verduras con los jugos de la fuente.\n● Coloca el salmón encima con la piel hacia abajo y añade ajo picado, hierbas y rodajas de limón.\n● Hornea todo entre 10 y 12 minutos, según el grosor de los lomos, para mantener el pescado jugoso.\n● Deja reposar 2 minutos y sirve el salmón con las verduras y unas gotas de limón.', '2026-04-18 20:30:00', '2026-08-26 10:40:21'),
(44, 21, '6a8c204c1b3a3_1787568204.jpg', '6a8c204c1b3a3_1787568204.png', '🍽️ Lasaña boloñesa\n\nCapas de pasta, salsa boloñesa y bechamel cubiertas con abundante queso gratinado.\n\n📜 Ingredientes:\n● 12 placas de lasaña\n● 500 g de carne picada\n● 500 g de tomate triturado\n● 1 cebolla\n● 1 zanahoria\n● 1 diente de ajo\n● 600 ml de leche\n● 50 g de harina\n● 50 g de mantequilla\n● 150 g de queso rallado\n● Aceite, sal, pimienta y nuez moscada\n\n🥣 Procedimiento:\n● Pica la cebolla, la zanahoria y el ajo y sofríelos con aceite durante 10 minutos.\n● Añade la carne, sepárala bien y cocínala hasta que se dore; incorpora el tomate y cocina 25 minutos.\n● Derrite la mantequilla, agrega la harina y remueve 2 minutos antes de añadir la leche poco a poco.\n● Cocina la bechamel hasta que espese y sazónala con sal, pimienta y nuez moscada.\n● Monta capas de pasta, boloñesa y bechamel y termina con una capa generosa de queso rallado.\n● Hornea a 190 °C durante 30 minutos y deja reposar 10 minutos para que las porciones mantengan la forma.', '2026-06-20 15:20:00', '2026-08-26 10:40:21'),
(45, 21, '6a8c205359d24_1787568211.jpg', '6a8c205359d24_1787568211.png', '🍽️ Risotto de setas\n\nUn risotto cremoso y lleno de aroma, con setas salteadas y parmesano recién rallado.\n\n📜 Ingredientes:\n● 300 g de arroz arborio\n● 350 g de setas variadas\n● 1 litro de caldo de verduras\n● 1 cebolla pequeña\n● 100 ml de vino blanco\n● 40 g de mantequilla\n● 80 g de queso parmesano\n● 2 cucharadas de aceite de oliva\n● Sal y pimienta\n\n🥣 Procedimiento:\n● Mantén el caldo caliente a fuego muy suave durante toda la preparación.\n● Limpia y corta las setas, saltéalas a fuego fuerte con aceite y resérvalas cuando estén doradas.\n● Sofríe la cebolla picada, añade el arroz y remueve durante 2 minutos para nacararlo.\n● Vierte el vino y deja que se evapore antes de añadir el primer cucharón de caldo.\n● Incorpora el caldo poco a poco mientras remueves y espera a que se absorba antes de añadir más.\n● Tras unos 18 minutos, agrega las setas, retira del fuego y mezcla con la mantequilla y el parmesano.', '2026-05-30 19:25:00', '2026-08-26 10:40:21'),
(46, 21, '6a8c205da132a_1787568221.jpg', '6a8c205da132a_1787568221.png', '🍽️ Poke de salmón y aguacate\n\nUn bol fresco y colorido con salmón marinado, arroz, verduras crujientes y aguacate.\n\n📜 Ingredientes:\n● 300 g de salmón previamente congelado y apto para consumo en crudo\n● 250 g de arroz\n● 1 aguacate\n● 1/2 pepino\n● 1 zanahoria\n● 100 g de edamame cocido\n● 3 cucharadas de salsa de soja\n● 1 cucharadita de aceite de sésamo\n● 1 lima\n● Semillas de sésamo\n\n🥣 Procedimiento:\n● Cuece el arroz, déjalo reposar tapado 10 minutos y espera a que se temple antes de montar el bol.\n● Corta el salmón en dados del mismo tamaño usando una tabla y un cuchillo bien limpios.\n● Mezcla la soja, el aceite de sésamo y el zumo de media lima y marina el salmón durante 10 minutos en frío.\n● Corta el pepino y la zanahoria en tiras finas y el aguacate en láminas.\n● Reparte el arroz en los boles y coloca encima el salmón, las verduras, el aguacate y el edamame.\n● Añade el resto de la lima, espolvorea las semillas de sésamo y sirve inmediatamente.', '2026-06-27 14:00:00', '2026-08-26 10:40:21'),
(47, 21, '6a8c20646e087_1787568228.jpg', '6a8c20646e087_1787568228.png', '🍽️ Lentejas estofadas con chorizo\n\nUn guiso de cuchara sabroso y reconfortante, perfecto para los días en los que apetece comida casera.\n\n📜 Ingredientes:\n● 350 g de lentejas pardinas\n● 150 g de chorizo\n● 1 patata grande\n● 2 zanahorias\n● 1 cebolla\n● 2 dientes de ajo\n● 1 tomate maduro\n● 1 cucharadita de pimentón\n● 1 hoja de laurel\n● 1,2 litros de agua\n● Aceite de oliva y sal\n\n🥣 Procedimiento:\n● Lava las lentejas, pela las verduras y corta la patata y la zanahoria en trozos regulares.\n● Sofríe la cebolla y el ajo picados hasta que estén tiernos y añade el tomate rallado.\n● Retira la cazuela unos segundos del fuego, incorpora el pimentón y remueve para evitar que se queme.\n● Añade las lentejas, el chorizo, las verduras y el laurel y cubre todo con el agua fría.\n● Cocina a fuego suave entre 40 y 50 minutos, removiendo ocasionalmente y añadiendo agua si fuera necesario.\n● Ajusta de sal al final, deja reposar el guiso 10 minutos y sírvelo bien caliente.', '2026-08-08 17:30:00', '2026-08-26 10:40:21'),
(48, 21, '6a8c206c0364a_1787568236.jpg', '6a8c206c0364a_1787568236.png', '🍽️ Croquetas de jamón\n\nCrujientes por fuera y muy cremosas por dentro, con todo el sabor del jamón.\n\n📜 Ingredientes:\n● 150 g de jamón serrano\n● 750 ml de leche entera\n● 90 g de harina\n● 90 g de mantequilla\n● 1/2 cebolla\n● Nuez moscada\n● 2 huevos\n● 200 g de pan rallado\n● Aceite para freír\n● Sal y pimienta\n\n🥣 Procedimiento:\n● Calienta la leche aparte y pica el jamón y la cebolla en trozos muy pequeños.\n● Derrite la mantequilla, cocina la cebolla hasta que esté transparente y añade la harina.\n● Remueve la harina durante 3 minutos y vierte la leche caliente poco a poco sin dejar de batir.\n● Cocina la bechamel hasta que se separe de las paredes, añade el jamón y sazona con nuez moscada y pimienta.\n● Extiende la masa en una fuente, cúbrela y enfríala durante al menos 6 horas.\n● Forma las croquetas, pásalas por huevo y pan rallado y fríelas por tandas hasta que estén doradas.', '2026-07-04 13:30:00', '2026-08-26 10:40:21'),
(49, 21, '6a8c207360d0f_1787568243.jpg', '6a8c207360d0f_1787568243.png', '🍽️ Empanadillas de pollo\n\nEmpanadillas doradas y crujientes con un relleno jugoso de pollo y verduras.\n\n📜 Ingredientes:\n● 12 obleas para empanadillas\n● 300 g de pollo cocido\n● 1 cebolla\n● 1/2 pimiento rojo\n● 150 g de tomate triturado\n● 1 huevo cocido\n● 1 cucharadita de pimentón\n● 1 huevo para pintar\n● Aceite de oliva y sal\n\n🥣 Procedimiento:\n● Pica la cebolla y el pimiento y sofríelos con aceite durante 10 minutos.\n● Añade el tomate y el pimentón y cocina hasta obtener un relleno espeso y sin exceso de líquido.\n● Incorpora el pollo desmenuzado y el huevo cocido picado, mezcla y deja enfriar por completo.\n● Coloca una cucharada de relleno en cada oblea sin llegar a los bordes.\n● Dobla las obleas, sella los bordes con un tenedor y colócalas en una bandeja.\n● Píntalas con huevo batido y hornéalas a 200 °C durante 15 minutos, hasta que estén doradas.', '2026-04-25 17:45:00', '2026-08-26 10:40:21'),
(50, 21, '6a8c207a8800a_1787568250.jpg', '6a8c207a8800a_1787568250.png', '🍽️ Ensalada de burrata y tomate\n\nUna ensalada fresca y sencilla en la que la burrata cremosa y los tomates maduros son los protagonistas.\n\n📜 Ingredientes:\n● 1 burrata de 200 g\n● 400 g de tomates variados\n● 60 g de rúcula\n● 8 hojas de albahaca fresca\n● 3 cucharadas de aceite de oliva virgen extra\n● 1 cucharada de vinagre balsámico\n● Sal en escamas\n● Pimienta negra\n\n🥣 Procedimiento:\n● Lava y seca bien los tomates, la rúcula y las hojas de albahaca.\n● Corta los tomates en tamaños diferentes y sazónalos con una pizca de sal.\n● Extiende la rúcula en una fuente y reparte los tomates por encima.\n● Escurre la burrata, colócala en el centro y ábrela ligeramente justo antes de servir.\n● Añade la albahaca, el aceite de oliva y unas gotas de vinagre balsámico.\n● Termina con sal en escamas y pimienta recién molida y sirve la ensalada inmediatamente.', '2026-05-09 14:10:00', '2026-08-26 10:40:21'),
(51, 21, '6a8c20825557a_1787568258.jpg', '6a8c20825557a_1787568258.png', '🍽️ Tarta de queso vasca\n\nUna tarta de queso muy cremosa por dentro, con la superficie tostada y un sabor irresistible.\n\n📜 Ingredientes:\n● 600 g de queso crema\n● 350 ml de nata para montar\n● 4 huevos\n● 180 g de azúcar\n● 20 g de harina\n\n🥣 Procedimiento:\n● Precalienta el horno a 210 °C y forra un molde de 20 cm con papel de horno humedecido.\n● Bate el queso crema con el azúcar a velocidad baja hasta que no queden grumos.\n● Incorpora los huevos uno a uno, mezclando bien antes de añadir el siguiente.\n● Agrega la nata y la harina tamizada y mezcla solo hasta obtener una crema homogénea.\n● Vierte la mezcla en el molde y hornea durante 40 minutos, hasta que la superficie esté muy tostada.\n● Deja que se enfríe por completo y guárdala unas horas en la nevera antes de cortarla.', '2026-06-13 14:35:00', '2026-08-26 10:40:21'),
(52, 21, '6a8c208a0bbbb_1787568266.jpg', '6a8c208a0bbbb_1787568266.png', '🍽️ Pizza margarita casera\n\nUna pizza de masa fina y bordes dorados con tomate, mozzarella y albahaca fresca.\n\n📜 Ingredientes:\n● 300 g de harina de fuerza\n● 190 ml de agua templada\n● 5 g de levadura seca de panadería\n● 6 g de sal\n● 1 cucharada de aceite de oliva\n● 180 g de tomate triturado\n● 200 g de mozzarella\n● Albahaca fresca\n\n🥣 Procedimiento:\n● Mezcla la harina con la levadura, añade el agua y amasa durante 5 minutos.\n● Incorpora la sal y el aceite y continúa amasando hasta obtener una masa lisa y elástica.\n● Forma una bola, tápala y déjala fermentar entre 1 y 2 horas, hasta que doble su volumen.\n● Precalienta el horno a su temperatura máxima con la bandeja dentro para que esté muy caliente.\n● Estira la masa, reparte una capa fina de tomate y añade la mozzarella bien escurrida.\n● Hornea hasta que los bordes estén dorados y termina con albahaca fresca y un hilo de aceite.', '2026-07-18 13:50:00', '2026-08-26 10:40:21'),
(53, 21, '6a8c209214a7f_1787568274.jpg', '6a8c209214a7f_1787568274.png', '🍽️ Pollo asado con verduras\n\nPollo dorado y jugoso acompañado de patatas, zanahoria y cebolla asadas en sus propios jugos.\n\n📜 Ingredientes:\n● 1 kg de pollo troceado\n● 500 g de patatas\n● 3 zanahorias\n● 2 cebollas\n● 4 dientes de ajo\n● 100 ml de vino blanco\n● 1 limón\n● 3 cucharadas de aceite de oliva\n● Romero y tomillo\n● Sal y pimienta\n\n🥣 Procedimiento:\n● Precalienta el horno a 200 °C y corta las patatas, las zanahorias y las cebollas en trozos similares.\n● Coloca las verduras en una fuente, añade la mitad del aceite, sal y pimienta y mezcla bien.\n● Sazona el pollo con el ajo picado, las hierbas, el resto del aceite y el zumo de medio limón.\n● Coloca el pollo sobre las verduras, vierte el vino por un lateral y añade el resto del limón en rodajas.\n● Hornea durante 50 minutos y da la vuelta al pollo a mitad de cocción para que se dore de manera uniforme.\n● Comprueba que el pollo esté completamente cocinado, deja reposar 5 minutos y sírvelo con las verduras.', '2026-05-23 20:05:00', '2026-08-26 10:40:21'),
(54, 23, '6a8c78b8dacc7_1787590840.jpg', '6a8c78b8dacc7_1787590840.png', 'Los últimos detalles antes de salir ✨ Top negro, piel luminosa y accesorios dorados: una combinación sencilla que siempre funciona.', '2026-08-11 19:34:00', '2026-08-26 10:40:21'),
(55, 23, '6a8c78c719fbd_1787590855.jpg', '6a8c78c719fbd_1787590855.png', '¡Estamos en la final! 🇪🇸 Qué tensión, qué partido y qué manera de celebrarlo con los de siempre. Hoy tocaba brindar por esta selección.', '2026-07-14 23:12:00', '2026-08-26 10:40:21'),
(56, 23, '6a8c78d544691_1787590869.jpg', '6a8c78d544691_1787590869.png', 'CAMPEONES DEL MUNDO 🇪🇸🏆 Todavía no me creo esta noche. Gritos, nervios, abrazos y una celebración que vamos a recordar toda la vida.', '2026-07-19 23:58:00', '2026-08-26 10:40:21'),
(57, 23, '6a8c78de7afea_1787590878.jpg', '6a8c78de7afea_1787590878.png', 'Probando un maquillaje suave para diario: tonos cálidos, pestañas definidas y una base ligera para que la piel siga pareciendo piel.', '2026-05-28 18:42:00', '2026-08-26 10:40:21'),
(58, 23, '6a8c78ea7bba5_1787590890.jpg', '6a8c78ea7bba5_1787590890.png', 'Publi! El delineado cambia por completo una mirada. Hoy lo he dejado fino, alargado y con un acabado limpio para que el protagonismo se quede en los ojos.', '2026-08-03 20:11:00', '2026-08-26 10:40:21'),
(59, 23, '6a8c78f48c286_1787590900.jpg', '6a8c78f48c286_1787590900.png', 'Una noche temática pedía algo diferente 🐆 Maquillaje felino, estampado de leopardo y muchas ganas de pasarlo bien. Salir de lo habitual también inspira.', '2026-04-18 23:26:00', '2026-08-26 10:40:21'),
(60, 23, '6a8c7905d6bf0_1787590917.jpg', '6a8c7905d6bf0_1787590917.png', 'Un día precioso acompañando a una de mis personas favoritas 🤍 Todas las damas juntas, la novia en el centro y muchísimos nervios antes de empezar.', '2026-06-20 18:35:00', '2026-08-26 10:40:21'),
(61, 23, '6a8c791c469bd_1787590940.jpg', '6a8c791c469bd_1787590940.png', 'Cuando todo el maquillaje es neutro, unos labios rojos hacen el trabajo entero 💄 Un clásico que nunca falla para transformar el look en segundos.', '2026-07-29 19:08:00', '2026-08-26 10:40:21'),
(62, 23, '6a8c79277952c_1787590951.jpg', '6a8c79277952c_1787590951.png', 'Una semana después de la boda, os enseño mejor el maquillaje que llevé como dama de honor: piel luminosa, colorete suave y ojos en tonos cálidos para aguantar todo el día.', '2026-06-27 12:35:00', '2026-08-26 10:40:21'),
(64, 23, '6a8c794284631_1787590978.jpg', '6a8c794284631_1787590978.png', 'Tres días después y sigo mirando las fotos de la boda con una sonrisa enorme 🤍 Qué suerte haber estado a tu lado en un día tan especial.', '2026-06-23 20:16:00', '2026-08-26 10:40:21'),
(65, 23, '6a8c794d5918f_1787590989.jpg', '6a8c794d5918f_1787590989.png', 'Mi forma favorita de aplicar la máscara: primero desde la raíz con movimientos suaves y después una segunda capa solo en las puntas para alargar sin apelmazar.', '2026-04-28 18:53:00', '2026-08-26 10:40:21'),
(66, 23, '6a8c795fb05d9_1787591007.jpg', '6a8c795fb05d9_1787591007.png', 'Un look cómodo para esos días en los que no quieres pensar demasiado: punto beige, vaqueros y unos pendientes dorados para darle un acabado un poco más cuidado.', '2026-08-21 18:14:00', '2026-08-26 10:40:21'),
(67, 23, '6a8c79769588a_1787591030.jpg', '6a8c79769588a_1787591030.png', 'Cuatro conjuntos, cuatro versiones completamente distintas. ¿Con cuál os quedáis: pantalón blanco, cuero negro, vaquero o el look cómodo de punto?', '2026-05-21 20:07:00', '2026-08-26 10:40:21'),
(68, 23, '6a8c798709381_1787591047.jpg', '6a8c798709381_1787591047.png', 'El dilema de siempre frente al armario: negro o blanco. Dos opciones sencillas, pero con personalidades totalmente diferentes según el plan.', '2026-04-06 17:38:00', '2026-08-26 10:40:21'),
(70, 23, '6a8c820672ad7_1787593222.jpg', '6a8c820672ad7_1787593222.png', 'Cena con vistas y un vestido blanco que necesitaba muy pocos accesorios. Algunas noches tienen la luz perfecta sin tener que buscarla.', '2026-08-09 22:31:00', '2026-08-26 10:40:21'),
(71, 23, '6a8c8217b6293_1787593239.jpg', '6a8c8217b6293_1787593239.png', 'Desayunar con el mar de fondo y sin mirar el reloj debería ser obligatorio más veces. Vestido ligero, maquillaje natural y mañana sin prisas.', '2026-05-03 10:22:00', '2026-08-26 10:40:21'),
(72, 23, '6a8c821f321d2_1787593247.jpg', '6a8c821f321d2_1787593247.png', 'Un vestido rojo y la ciudad encendiéndose detrás. Tenía claro el color, pero no esperaba que la luz del atardecer hiciera el resto tan bien.', '2026-08-16 20:44:00', '2026-08-26 10:40:21'),
(73, 23, '6a8c82347873b_1787593268.jpg', '6a8c82347873b_1787593268.png', 'Los tonos neutros también pueden tener presencia. Traje beige, líneas limpias y accesorios mínimos para dejar que el conjunto hable por sí solo.', '2026-04-23 17:26:00', '2026-08-26 10:40:21'),
(74, 23, '6a8c823c35f7d_1787593276.jpg', '6a8c823c35f7d_1787593276.png', 'Tarde junto al mar con un vestido blanco ligero y el pelo suelto. El tipo de look que funciona mejor cuanto menos intentas complicarlo.', '2026-07-07 19:48:00', '2026-08-26 10:40:21'),
(75, 23, '6a8c82495420f_1787593289.jpg', '6a8c82495420f_1787593289.png', 'Total black, gabardina camel y un bolso pequeño. Una mezcla clásica para recorrer la ciudad sin renunciar a ir arreglada.', '2026-05-17 18:12:00', '2026-08-26 10:40:21'),
(76, 23, '6a8c8250ab1a4_1787593296.jpg', '6a8c8250ab1a4_1787593296.png', 'El vestido floral perfecto para días de calor 🌿 Tejido ligero, movimiento y colores suaves para un look cómodo que sigue viéndose especial.', '2026-06-09 13:42:00', '2026-08-26 10:40:21'),
(77, 23, '6a8c82576f113_1787593303.jpg', '6a8c82576f113_1787593303.png', 'Vestido coral, paseo junto al mar y uno de los mejores atardeceres del viaje. Hay colores que parecen hechos para la hora dorada.', '2026-07-24 20:51:00', '2026-08-26 10:40:21'),
(78, 23, '6a8c825e1ee8a_1787593310.jpg', '6a8c825e1ee8a_1787593310.png', 'Un conjunto verde suave para perderme por calles antiguas y llenas de flores. Cómodo, fresco y perfecto para caminar durante horas.', '2026-03-29 12:18:00', '2026-08-26 10:40:21'),
(79, 23, '6a8c82660ed7b_1787593318.jpg', '6a8c82660ed7b_1787593318.png', 'Traje blanco para cerrar la semana con un café tranquilo. Me encanta mezclar prendas elegantes con planes cotidianos para que no se queden esperando una ocasión especial.', '2026-08-23 11:37:00', '2026-08-26 10:40:21'),
(80, 24, '6a8c8ec81e831_1787596488.jpg', '6a8c8ec81e831_1787596488.png', 'Una tarde de galletas con mis tres ayudantes favoritos 🍪 La cocina terminó llena de harina, pero ellos estaban tan orgullosos de sus formas que mereció totalmente la pena.', '2026-08-06 17:42:00', '2026-08-26 10:40:22'),
(81, 24, '6a8c8ecfe3f3b_1787596495.jpg', '6a8c8ecfe3f3b_1787596495.png', 'Desayuno especial hecho entre todos: uno mezcla, otra coloca la fruta y el pequeño intenta probarlo todo antes de terminar. Así es imposible que las tortitas salgan perfectas, pero saben mucho mejor.', '2026-04-24 10:18:00', '2026-08-26 10:40:22'),
(82, 24, '6a8c8eed2aa10_1787596525.jpg', '6a8c8eed2aa10_1787596525.png', 'Noche de juegos en casa 🎲 Empezamos diciendo que sería una partida rápida y acabamos negociando reglas inventadas, compartiendo palomitas y riéndonos durante horas.', '2026-06-29 20:11:00', '2026-08-26 10:40:22'),
(83, 24, '6a8c8ef416b1c_1787596532.jpg', '6a8c8ef416b1c_1787596532.png', 'Primera excursión larga de los cuatro hasta esta cascada. Hubo barro, alguna queja y muchas paradas, pero ver sus caras al llegar hizo que todo el camino mereciera la pena.', '2026-03-12 16:37:00', '2026-08-26 10:40:22'),
(84, 24, '6a8c8efba5bcd_1787596539.jpg', '6a8c8efba5bcd_1787596539.png', 'Un paseo sin horarios por calles blancas, flores por todas partes y el mar apareciendo al fondo. También necesito estos ratitos tranquilos para volver a casa con las pilas cargadas.', '2026-03-01 12:26:00', '2026-08-26 10:40:22'),
(85, 24, '6a8c8f0312188_1787596547.jpg', '6a8c8f0312188_1787596547.png', 'Visita al mercado para elegir ingredientes frescos para la semana. Me encanta hablar con quienes conocen cada producto y volver a casa con nuevas ideas para las comidas.', '2026-05-27 11:08:00', '2026-08-26 10:40:22'),
(86, 24, '6a8c8f0b61d1a_1787596555.jpg', '6a8c8f0b61d1a_1787596555.png', 'Cocinando algo sencillo mientras la casa está en calma. Un poco de verdura, una salsa hecha sin prisas y ese raro momento en el que nadie pregunta cuánto falta para cenar.', '2026-02-24 19:36:00', '2026-08-26 10:40:22'),
(87, 24, '6a8c8f124f6e8_1787596562.jpg', '6a8c8f124f6e8_1787596562.png', 'Té caliente, ropa cómoda y unas páginas antes de dormir. No siempre consigo tener un rato para mí, así que cuando aparece intento disfrutarlo sin sentir que debería estar haciendo otra cosa.', '2026-03-22 21:14:00', '2026-08-26 10:40:22'),
(88, 24, '6a8c8f1b54eba_1787596571.jpg', '6a8c8f1b54eba_1787596571.png', 'Una cena tranquila, conversación sin interrupciones y la comida todavía caliente cuando llega a la mesa. Después de tantos planes familiares, una noche así también se agradece muchísimo.', '2026-07-08 22:03:00', '2026-08-26 10:40:22'),
(89, 24, '6a8c8f23767dd_1787596579.jpg', '6a8c8f23767dd_1787596579.png', 'Café temprano en una terraza y un paseo sin rumbo por la ciudad. Viajar también consiste en sentarse un rato, mirar alrededor y no intentar verlo absolutamente todo.', '2026-08-14 09:47:00', '2026-08-26 10:40:22'),
(90, 24, '6a8c8f2d8c54e_1787596589.jpg', '6a8c8f2d8c54e_1787596589.png', 'Hoy solo tenía cuarenta minutos, pero fueron suficientes. Entrenar no siempre significa hacerlo perfecto: a veces simplemente consiste en reservar un pequeño espacio para cuidarme.', '2026-05-05 18:29:00', '2026-08-26 10:40:22'),
(91, 24, '6a8c8f34d3ad7_1787596596.jpg', '6a8c8f34d3ad7_1787596596.png', 'Después de una buena caminata apareció este lago entre las montañas. Silencio, aire frío y unas vistas que hicieron que quisiera quedarme allí mucho más tiempo.', '2026-07-28 13:16:00', '2026-08-26 10:40:22'),
(92, 24, '6a8c8f3ddecc7_1787596605.jpg', '6a8c8f3ddecc7_1787596605.png', 'Un paseo junto al mar antes de volver con los niños. Vestido ligero, bolso grande para llevar de todo y unos minutos escuchando las olas sin ninguna prisa.', '2026-06-18 18:51:00', '2026-08-26 10:40:22'),
(93, 24, '6a8c8f458b706_1787596613.jpg', '6a8c8f458b706_1787596613.png', 'Día de reuniones y recados por la ciudad. Un traje claro, zapatos cómodos y café en mano para intentar llegar a todo sin perder la cabeza.', '2026-04-13 16:22:00', '2026-08-26 10:40:22'),
(94, 24, '6a8c982d81671_1787598893.jpg', '6a8c982d81671_1787598893.png', 'Mesa llena de papeles, pegamento y pequeñas obras de arte 🎨 Cada uno tenía una idea distinta y, como siempre, terminamos creando algo completamente diferente a lo que habíamos planeado.', '2026-04-02 17:33:00', '2026-08-26 10:40:22'),
(95, 24, '6a8c983527f44_1787598901.jpg', '6a8c983527f44_1787598901.png', 'El cuento de antes de dormir se convirtió en tres cuentos, muchas preguntas y una última página repetida dos veces. Estos ratitos bajo la manta son puro hogar.', '2026-08-23 20:46:00', '2026-08-26 10:40:22'),
(96, 24, '6a8c983bd0976_1787598907.jpg', '6a8c983bd0976_1787598907.png', 'Construcción importante junto al mar 🏖️ Tres arquitectos, demasiados cubos y una madre intentando que el castillo sobreviviera hasta la foto.', '2026-05-16 12:41:00', '2026-08-26 10:40:22'),
(97, 24, '6a8c9842a80fb_1787598914.jpg', '6a8c9842a80fb_1787598914.png', 'Picnic improvisado bajo los árboles: fruta, bocadillos, cuentos y toda la tarde por delante. Los planes más sencillos suelen ser los que mejor recuerdan.', '2026-07-19 13:07:00', '2026-08-26 10:40:22'),
(98, 24, '6a8c984c759ee_1787598924.jpg', '6a8c984c759ee_1787598924.png', 'Domingo de tortitas con los tres alrededor de la mesa 🥞 Entre fruta, chocolate y manos impacientes, preparar el desayuno juntos ya se ha convertido en una de nuestras pequeñas tradiciones.', '2026-06-08 09:34:00', '2026-08-26 10:40:22'),
(99, 26, '6a8d43141b7b2_1787642644.jpg', '6a8d43141b7b2_1787642644.png', '📍 Indonesia — Raja Ampat\r\n📸 Laura Martín', '2026-03-02 10:31:13', '2026-08-26 10:40:22'),
(100, 26, '6a8d453172781_1787643185.jpg', '6a8d453172781_1787643185.png', '📍 Bolivia — Salar de Uyuni\r\n📸 Daniel Herrera', '2026-07-14 16:27:14', '2026-08-26 10:40:22'),
(101, 26, '6a8d45cfa329a_1787643343.jpg', '6a8d45cfa329a_1787643343.png', '📍 Camboya — Templo de Ta Prohm, Angkor\r\n📸 Sofía Navarro', '2026-03-29 08:10:14', '2026-08-26 10:40:22'),
