(119, 26, '6a8d487ba1178_1787644027.jpg', '6a8d487ba1178_1787644027.png', '📍 Estados Unidos — Mammoth Hot Springs, Yellowstone\r\n📸 Valeria Santos', '2026-04-11 14:05:05', '2026-08-26 10:40:22'),
(120, 26, '6a8d4884c99ef_1787644036.jpg', '6a8d4884c99ef_1787644036.png', '📍 Grecia — Cuevas Azules de Zante\r\n📸 Nicolás Rivas', '2026-04-22 11:14:43', '2026-08-26 10:40:22'),
(122, 25, '6a8d5a1fddc4c_1787648543.jpg', '6a8d5a1fddc4c_1787648543.png', 'Día de poner lavadoras y convencerme de que ordenar la habitación también cuenta como ser productivo.', '2026-07-10 08:20:16', '2026-08-26 10:40:22'),
(123, 25, '6a8d5a2695ddd_1787648550.jpg', '6a8d5a2695ddd_1787648550.png', 'Comida improvisada con mi persona favorita. Al final nos quedamos hablando toda la tarde.', '2026-03-25 17:28:31', '2026-08-26 10:40:22'),
(124, 25, '6a8d5a2d30f9d_1787648557.jpg', '6a8d5a2d30f9d_1787648557.png', 'Cinco minutos mirando el móvil y de repente había pasado una hora. Lo normal.', '2026-04-27 09:23:03', '2026-08-26 10:40:22'),
(125, 25, '6a8d5a343e7e0_1787648564.jpg', '6a8d5a343e7e0_1787648564.png', 'He venido a por un libro para clase y ya llevo tres que no estaban en la lista.', '2026-06-25 08:22:29', '2026-08-26 10:40:22'),
(126, 25, '6a8d5a3b0c7a7_1787648571.jpg', '6a8d5a3b0c7a7_1787648571.png', 'Paseo después de comer y una foto rápida antes de que empezara a llover.', '2026-08-23 08:57:51', '2026-08-26 10:40:22'),
(127, 25, '6a8d5a4235096_1787648578.jpg', '6a8d5a4235096_1787648578.png', 'Café en mano y directo a clase. Hoy tocaba madrugar más de lo razonable.', '2026-06-02 10:31:42', '2026-08-26 10:40:22'),
(128, 25, '6a8d5a4934c5b_1787648585.jpg', '6a8d5a4934c5b_1787648585.png', 'Un rato por el parque para despejarme después de pasar toda la mañana estudiando.', '2026-07-31 13:07:12', '2026-08-26 10:40:22'),
(129, 25, '6a8d5a5192521_1787648593.jpg', '6a8d5a5192521_1787648593.png', 'Cena rápida entre apuntes. No será de restaurante, pero ha quedado bastante bien.', '2026-04-06 11:12:23', '2026-08-26 10:40:22'),
(130, 25, '6a8d93b424eed_1787663284.jpg', '6a8d93b424eed_1787663284.png', 'Intentando terminar un trabajo en la cafetería sin distraerme cada dos minutos.', '2026-05-09 20:18:12', '2026-08-26 10:40:22'),
(131, 25, '6a8d93c8d3435_1787663304.jpg', '6a8d93c8d3435_1787663304.png', 'Tren de vuelta a casa y por fin un rato para no hacer absolutamente nada.', '2026-06-14 20:31:15', '2026-08-26 10:40:22'),
(132, 4, '6a8dc57d224a8_1787676029.jpg', '6a8dc57d224a8_1787676029.png', NULL, '2026-08-25 18:40:29', '2026-08-26 10:40:22'),
(133, 4, '6a8dc58539408_1787676037.jpg', '6a8dc58539408_1787676037.png', 'Café caliente y tostada en la plaza antes de seguir camino. Los pueblos se disfrutan sin mirar el reloj.', '2026-03-20 12:38:56', '2026-08-26 10:40:22'),
(134, 4, '6a8dc58c82195_1787676044.jpg', '6a8dc58c82195_1787676044.png', 'Cena sencilla con lo que encontré en el mercado. Cocinar despacio también forma parte del viaje.', '2026-06-27 14:16:30', '2026-08-26 10:40:22'),
(135, 4, '6a8dc593c3122_1787676051.jpg', '6a8dc593c3122_1787676051.png', 'Ventanilla, montañas y unas cuantas horas por delante. No necesito mucho más para empezar una aventura.', '2026-07-25 19:15:17', '2026-08-26 10:40:22'),
(136, 4, '6a8dc59cae897_1787676060.jpg', '6a8dc59cae897_1787676060.png', 'Primera vez recorriendo este lago en kayak. El agua estaba helada, pero las vistas merecían cada palada.', '2026-04-04 19:49:18', '2026-08-26 10:40:22'),
(137, 4, '6a8dc5dee706b_1787676126.jpg', '6a8dc5dee706b_1787676126.png', 'Sendero junto a los acantilados y viento de cara durante casi todo el camino. Día duro, cabeza despejada.', '2026-05-03 15:50:30', '2026-08-26 10:40:22'),
(138, 4, '6a8dc5e5947df_1787676133.jpg', '6a8dc5e5947df_1787676133.png', 'Parada en el mercado del pueblo para llenar la mochila. Siempre termino hablando más de la cuenta con quien vende la fruta.', '2026-08-05 10:51:23', '2026-08-26 10:40:22'),
(139, 4, '6a8dc5ec15593_1787676140.jpg', '6a8dc5ec15593_1787676140.png', 'Noche de tienda, linterna y un cielo completamente limpio. Aquí fuera se duerme de otra manera.', '2026-05-17 08:01:22', '2026-08-26 10:40:22'),
(140, 4, '6a8dc5f41a3b2_1787676148.jpg', '6a8dc5f41a3b2_1787676148.png', 'Encontrar esta cascada al final del sendero ha sido el mejor premio de la mañana.', '2026-04-18 15:29:54', '2026-08-26 10:40:22'),
(143, 4, '6a8dc620e7eeb_1787676192.jpg', '6a8dc620e7eeb_1787676192.png', 'Carretera secundaria, viñedos y alforjas cargadas. Hoy las piernas han trabajado de verdad 🚲 Entre subidas, curvas y algún descanso para disfrutar del paisaje, ha sido una de esas rutas que cansan pero merecen muchísimo la pena. Kilómetros, aire fresco y ganas de seguir descubriendo lugares nuevos. 🍇⛰️', '2026-06-13 15:42:31', '2026-08-26 12:55:47'),
(144, 4, '6a8dc628db9ba_1787676200.jpg', '6a8dc628db9ba_1787676200.png', 'Ruinas, caminos de piedra y ninguna prisa por llegar. Me podría quedar horas imaginando cómo era este lugar.', '2026-05-31 19:25:33', '2026-08-26 10:40:22');
INSERT INTO `images` (`id`, `user_id`, `image_path`, `original_name`, `description`, `created_at`, `updated_at`) VALUES
(145, 4, '6a8dc638cc2c1_1787676216.jpg', '6a8dc638cc2c1_1787676216.png', 'Último café en cubierta antes de llegar al siguiente pueblo costero. El mar estaba sorprendentemente tranquilo.', '2026-07-09 08:45:40', '2026-08-26 10:40:22'),
(146, 4, '6a8dc6401df3c_1787676224.jpg', '6a8dc6401df3c_1787676224.png', 'Despertar con el pueblo cubierto de nieve compensa el frío y las botas mojadas.', '2026-03-08 21:09:14', '2026-08-26 10:40:22'),
(147, 25, '6a8dc766baec5_1787676518.jpg', '6a8dc766baec5_1787676518.png', 'Una pausa entre clases. El café estaba mejor de lo que esperaba, sinceramente.', '2026-08-13 09:06:47', '2026-08-26 10:40:22'),
(148, 25, '6a8dc76cd5c85_1787676524.jpg', '6a8dc76cd5c85_1787676524.png', 'Compra de supervivencia estudiantil: algo sano, algo fácil y demasiados caprichos.', '2026-03-14 15:35:25', '2026-08-26 10:40:22'),
(149, 25, '6a8dc772dbee3_1787676530.jpg', '6a8dc772dbee3_1787676530.png', 'He entrado solo a mirar y he salido con otro disco. Era bastante previsible.', '2026-04-16 19:24:24', '2026-08-26 10:40:22'),
(150, 25, '6a8dc77a1c921_1787676538.jpg', '6a8dc77a1c921_1787676538.png', 'Volviendo de clase con la mochila pesando el doble que esta mañana.', '2026-05-20 21:48:39', '2026-08-26 10:40:22'),
(151, 25, '6a8dc7f1a5422_1787676657.jpg', '6a8dc7f1a5422_1787676657.png', 'Plan de esta noche: sofá, sudadera y no abrir los apuntes hasta mañana.', '2026-07-21 13:53:48', '2026-08-26 10:40:22'),
(154, 27, '6a8dcce3894ef_1787677923.jpg', '6a8dcce3894ef_1787677923.png', '📍 Laguna glaciar Jökulsárlón, Islandia\r\nUn paisaje que impone de verdad: hielo azul, silencio y viento constante. Conviene venir con ropa impermeable y tiempo para recorrer la orilla sin prisas.', '2026-07-08 15:24:40', '2026-08-26 10:40:22'),
(155, 27, '6a8dccee8b73d_1787677934.jpg', '6a8dccee8b73d_1787677934.png', '📍 Salar de Uyuni, Bolivia\r\nCuando hay una fina capa de agua, el cielo parece continuar bajo tus pies. La experiencia es increíble, aunque la altura y el frío se notan bastante.', '2026-08-20 13:28:41', '2026-08-26 10:40:22'),
(156, 27, '6a8dccf964d1b_1787677945.jpg', '6a8dccf964d1b_1787677945.png', '📍 Terrazas de arroz de Tegallalang, Bali, Indonesia\r\nVer cómo las terrazas siguen la forma de la montaña merece mucho la pena. Mejor llegar temprano: hay menos gente, menos calor y una luz preciosa.', '2026-03-05 11:03:30', '2026-08-26 10:40:22'),
(157, 27, '6a8dcd039a5a8_1787677955.jpg', '6a8dcd039a5a8_1787677955.png', '📍 Cenote Ik Kil, Yucatán, México\r\nEl agua fresca después del calor de Yucatán sienta de maravilla. Es un sitio espectacular, pero recomiendo ir a primera hora para disfrutarlo con calma.', '2026-04-17 10:36:56', '2026-08-26 10:40:22'),
(158, 27, '6a8dcd0d8a891_1787677965.jpg', '6a8dcd0d8a891_1787677965.png', '📍 Parque Nacional de Tarangire, Tanzania\r\nBaobabs, tierra roja y una sensación de espacio difícil de explicar. Un lugar magnífico para observar fauna respetando siempre las distancias.', '2026-06-11 14:34:17', '2026-08-26 10:40:22'),
(159, 27, '6a8dcd15a0ff9_1787677973.jpg', '6a8dcd15a0ff9_1787677973.png', '📍 Dead Horse Point, Utah, Estados Unidos\r\nLas curvas del río Colorado vistas desde arriba son brutales. El sendero es accesible, pero hay poca sombra y el agua es imprescindible.', '2026-04-01 15:22:56', '2026-08-26 10:40:22'),
(160, 27, '6a8dcd1ce3c0f_1787677980.jpg', '6a8dcd1ce3c0f_1787677980.png', '📍 El Nido, Palawan, Filipinas\r\nAgua transparente y paredes de piedra caliza por todas partes. El recorrido en barca es inolvidable; elegir un grupo pequeño mejora muchísimo la visita.', '2026-08-08 21:42:04', '2026-08-26 10:40:22'),
(161, 27, '6a8dcd244eca1_1787677988.jpg', '6a8dcd244eca1_1787677988.png', '📍 Hoh Rain Forest, Washington, Estados Unidos\r\nMusgo, helechos gigantes y una humedad que lo cubre todo. Caminar aquí parece entrar en otro mundo; llevar buen calzado marca la diferencia.', '2026-07-23 10:23:09', '2026-08-26 10:40:22'),
(162, 27, '6a8dcd2d94d59_1787677997.jpg', '6a8dcd2d94d59_1787677997.png', '📍 Dunn\'s River Falls, Jamaica\r\nUna sucesión de piscinas naturales perfecta para refrescarse. Las rocas resbalan bastante, así que aconsejo calzado de agua y avanzar sin prisas.', '2026-05-26 15:54:18', '2026-08-26 10:40:22'),
(163, 27, '6a8dcd3432b1b_1787678004.jpg', '6a8dcd3432b1b_1787678004.png', '📍 Dolomitas, Italia\r\nUno de esos lugares donde cada curva abre una vista nueva. Las rutas están muy bien señalizadas y el esfuerzo se recompensa de sobra.', '2026-06-23 12:52:09', '2026-08-26 10:40:22'),
(164, 27, '6a8dcd3b70448_1787678011.jpg', '6a8dcd3b70448_1787678011.png', '📍 Moorea, Polinesia Francesa\r\nPlayas tranquilas, montañas verdes y un ritmo que invita a quedarse. No es un destino barato, pero sus paisajes y fondos marinos son excepcionales.', '2026-03-20 08:41:58', '2026-08-26 10:40:22'),
(165, 27, '6a8dcd4375383_1787678019.jpg', '6a8dcd4375383_1787678019.png', '📍 Cataratas Nauyaca, Costa Rica\r\nLa caminata es calurosa, pero llegar a esta poza rodeada de selva compensa cada paso. Mejor llevar agua, repelente y una bolsa impermeable.', '2026-05-01 09:18:57', '2026-08-26 10:40:22'),
(166, 27, '6a8dcd4b1c6a1_1787678027.jpg', '6a8dcd4b1c6a1_1787678027.png', '📍 Parque Nacional de Tongariro, Nueva Zelanda\r\nTerreno volcánico, viento cambiante y vistas enormes. Es una ruta exigente: hay que revisar la previsión y salir bien equipado.', '2026-05-14 19:05:21', '2026-08-26 10:40:22'),
(167, 29, '6a8dcf5731698_1787678551.jpg', '6a8dcf5731698_1787678551.png', 'Empezar el día arriba cambia por completo la energía. Ruta, aire frío y piernas trabajando ⛰️', '2026-05-16 13:40:51', '2026-08-26 10:40:22'),
(168, 29, '6a8dcf5db82bf_1787678557.jpg', '6a8dcf5db82bf_1787678557.png', 'Kilómetros junto al mar para despejar la cabeza. La constancia también se entrena 🏃‍♂️', '2026-03-01 08:04:26', '2026-08-26 10:40:22'),
(169, 29, '6a8dcf646a981_1787678564.jpg', '6a8dcf646a981_1787678564.png', 'Mi batido de después de entrenar: sencillo, rápido y justo lo que necesito para recuperar 💪', '2026-07-22 16:42:10', '2026-08-26 10:40:22'),
(170, 29, '6a8dcf6c6a579_1787678572.jpg', '6a8dcf6c6a579_1787678572.png', 'Dejar la comida preparada me ayuda a cumplir incluso en los días más largos. Disciplina antes que excusas.', '2026-08-24 14:45:43', '2026-08-26 10:40:22'),
(171, 29, '6a8dcf7469d00_1787678580.jpg', '6a8dcf7469d00_1787678580.png', 'Sesión terminada. Hoy tocó técnica, control y no correr detrás de los pesos.', '2026-04-02 18:16:48', '2026-08-26 10:40:22'),
(172, 29, '6a8dcf7bac0c4_1787678587.jpg', '6a8dcf7bac0c4_1787678587.png', 'Un poco más fuerte que la semana pasada. Esos pequeños avances son los que cuentan 🔥', '2026-06-29 19:44:50', '2026-08-26 10:40:22'),
(173, 29, '6a8dcf8713143_1787678599.jpg', '6a8dcf8713143_1787678599.png', 'Total black para una noche de pasarela. Siempre hay algo especial en pisar el runway.', '2026-06-19 20:50:21', '2026-08-26 10:40:22'),
(174, 29, '6a8dcf8d96e91_1787678605.jpg', '6a8dcf8d96e91_1787678605.png', 'Luces, música y concentración. Otro desfile que se queda guardado entre mis favoritos.', '2026-04-25 11:01:47', '2026-08-26 10:40:22'),
(175, 29, '6a8dcf9753100_1787678615.jpg', '6a8dcf9753100_1787678615.png', 'Sastrería oscura y actitud. Me encanta cuando un look habla antes de que digas una palabra.', '2026-08-11 18:01:27', '2026-08-26 10:40:22'),
(176, 29, '6a8dcf9f2fc04_1787678623.jpg', '6a8dcf9f2fc04_1787678623.png', 'Nueva colección, nueva energía. Gracias a todo el equipo que hizo posible este desfile.', '2026-08-04 13:24:59', '2026-08-26 10:40:22'),
(177, 29, '6a8dcfa610cd2_1787678630.jpg', '6a8dcfa610cd2_1787678630.png', 'Un momento entre tomas en el estudio. A veces las fotos más simples son las que mejor funcionan.', '2026-05-08 12:17:03', '2026-08-26 10:40:22'),
(178, 29, '6a8dcfad8ef0e_1787678637.jpg', '6a8dcfad8ef0e_1787678637.png', 'Prueba de vestuario con vistas. Últimos ajustes antes de empezar la sesión 📸', '2026-03-10 10:18:29', '2026-08-26 10:40:22'),
(179, 29, '6a8dcfb538107_1787678645.jpg', '6a8dcfb538107_1787678645.png', 'Look cómodo para moverme por la ciudad entre castings y reuniones.', '2026-07-10 18:25:36', '2026-08-26 10:40:22'),
(180, 29, '6a8dcfbc1ecf4_1787678652.jpg', '6a8dcfbc1ecf4_1787678652.png', 'Día tranquilo en casa. Descansar también forma parte del progreso.', '2026-06-09 20:10:31', '2026-08-26 10:40:22'),
(181, 29, '6a8dcfc411bb3_1787678660.jpg', '6a8dcfc411bb3_1787678660.png', 'Ese momento después de entrenar en el que sabes que has dado todo lo que tenías.', '2026-05-30 12:47:07', '2026-08-26 10:40:22'),
(182, 29, '6a8dcfcbb5a31_1787678667.jpg', '6a8dcfcbb5a31_1787678667.png', 'Rodaje suave por el parque para cerrar la semana con buenas sensaciones.', '2026-03-23 21:44:06', '2026-08-26 10:40:22'),
(183, 29, '6a8dcfd4c0f3e_1787678676.jpg', '6a8dcfd4c0f3e_1787678676.png', 'Cocinar en casa, controlar lo que como y disfrutar del proceso. El equilibrio también se construye.', '2026-04-12 15:50:07', '2026-08-26 10:40:22'),
(184, 28, '6a8dd257e1e43_1787679319.jpg', '6a8dd257e1e43_1787679319.png', 'Hoy he subido pasta fresca casera a YouTube 🍝 Tienes la receta completa en YouTube/RecetasConMari. ¡No olvides seguirme!', '2026-07-24 10:59:03', '2026-08-26 10:40:22'),
(185, 28, '6a8dd2624258f_1787679330.jpg', '6a8dd2624258f_1787679330.png', '¡Nueva receta! Hoy preparamos tortilla de patatas en YouTube 🥔 Sígueme en YouTube/RecetasConMari para no perderte ninguna.', '2026-08-04 12:00:14', '2026-08-26 10:40:22'),
(186, 28, '6a8dd26c0b0f4_1787679340.jpg', '6a8dd26c0b0f4_1787679340.png', 'Hoy he subido salmón al horno con hierbas a YouTube 🐟 La receta paso a paso está en YouTube/RecetasConMari. ¡No olvides seguirme!', '2026-06-05 15:48:44', '2026-08-26 10:40:22'),
(187, 28, '6a8dd277ef9d5_1787679351.jpg', '6a8dd277ef9d5_1787679351.png', 'Ya tienes mi nueva pizza casera en YouTube 🍕 Pásate por YouTube/RecetasConMari y sígueme para ver las próximas recetas.', '2026-05-26 17:41:03', '2026-08-26 10:40:22'),
(188, 28, '6a8dd281cdd00_1787679361.jpg', '6a8dd281cdd00_1787679361.png', 'Hoy toca tacos de pollo y aguacate 🌮 Acabo de subir la receta a YouTube/RecetasConMari. ¡No olvides seguirme!', '2026-08-21 10:45:50', '2026-08-26 10:40:22'),
(189, 28, '6a8dd28f44614_1787679375.jpg', '6a8dd28f44614_1787679375.png', 'He subido unas tortitas esponjosas perfectas para desayunar 🥞 Mira el vídeo en YouTube/RecetasConMari y sígueme para más recetas.', '2026-07-14 20:49:40', '2026-08-26 10:40:22'),
(190, 28, '6a8dd2967f7af_1787679382.jpg', '6a8dd2967f7af_1787679382.png', 'Nueva receta de ramen con huevo y setas en YouTube 🍜 La tienes completa en YouTube/RecetasConMari. ¡No olvides seguirme!', '2026-08-11 17:42:30', '2026-08-26 10:40:22'),
(191, 28, '6a8dd29ce6d0b_1787679388.jpg', '6a8dd29ce6d0b_1787679388.png', 'Hoy he subido mi curry de verduras a YouTube 🥣 Encuentra todos los pasos en YouTube/RecetasConMari y sígueme.', '2026-05-08 18:34:13', '2026-08-26 10:40:22'),
(192, 28, '6a8dd2a52d2f3_1787679397.jpg', '6a8dd2a52d2f3_1787679397.png', 'La receta de hoy es una tarta de chocolate irresistible 🍫 Ya está disponible en YouTube/RecetasConMari. ¡No olvides seguirme!', '2026-04-10 17:34:20', '2026-08-26 10:40:22'),
(193, 28, '6a8dd2c1726f3_1787679425.jpg', '6a8dd2c1726f3_1787679425.png', 'Hoy hacemos galletas de mantequilla caseras 🍪 He subido el vídeo completo a YouTube/RecetasConMari. ¡Sígueme para no perderte el siguiente!', '2026-07-03 18:16:23', '2026-08-26 10:40:22'),
(194, 28, '6a8dd2cee0e1f_1787679438.jpg', '6a8dd2cee0e1f_1787679438.png', 'Acabo de subir mi risotto de champiñones a YouTube 🍄 La receta está en YouTube/RecetasConMari. ¡No olvides seguirme!', '2026-06-26 10:07:40', '2026-08-26 10:40:22'),
(195, 28, '6a8dd2d8ab293_1787679448.jpg', '6a8dd2d8ab293_1787679448.png', 'Hoy he subido cupcakes de vainilla a YouTube 🧁 Mira cómo quedan en YouTube/RecetasConMari y sígueme para más ideas dulces.', '2026-03-31 10:15:02', '2026-08-26 10:40:22'),
(196, 28, '6a8dd2df4f71c_1787679455.jpg', '6a8dd2df4f71c_1787679455.png', '¡Día de receta nueva! Ya puedes preparar conmigo estos ñoquis caseros en YouTube/RecetasConMari. No olvides seguirme 🍽️', '2026-04-28 10:29:48', '2026-08-26 10:40:22'),
(197, 28, '6a8dd2e6c9c5e_1787679462.jpg', '6a8dd2e6c9c5e_1787679462.png', 'Hoy he subido crepes caseros con fruta a YouTube 🍓 Tienes el paso a paso en YouTube/RecetasConMari. ¡Sígueme para más recetas!', '2026-05-19 10:34:10', '2026-08-26 10:40:22'),
(198, 28, '6a8dd2ee85d44_1787679470.jpg', '6a8dd2ee85d44_1787679470.png', 'Nueva lasaña casera en el canal 🧀 El vídeo completo ya está en YouTube/RecetasConMari. ¡No olvides seguirme!', '2026-04-21 10:00:35', '2026-08-26 10:40:22'),
(199, 28, '6a8dd2f521515_1787679477.jpg', '6a8dd2f521515_1787679477.png', 'Hoy preparamos croquetas caseras y ya he subido la receta a YouTube 🥖 Encuéntrala en YouTube/RecetasConMari y sígueme.', '2026-03-13 16:25:30', '2026-08-26 10:40:22'),
(200, 28, '6a8dd2fc86e07_1787679484.jpg', '6a8dd2fc86e07_1787679484.png', 'Mi nuevo curry de garbanzos y coco ya está en YouTube 🥣 Pásate por YouTube/RecetasConMari para ver la receta completa. ¡No olvides seguirme!', '2026-03-20 19:19:58', '2026-08-26 10:40:22'),
(201, 28, '6a8dd30431c9f_1787679492.jpg', '6a8dd30431c9f_1787679492.png', 'Hoy he subido bruschettas de tomate y verduras asadas a YouTube 🍅 La receta está en YouTube/RecetasConMari. ¡Sígueme para no perderte ninguna!', '2026-03-03 17:02:22', '2026-08-26 10:40:22'),
(202, 28, '6a8dd30b86bf0_1787679499.jpg', '6a8dd30b86bf0_1787679499.png', 'Nueva receta de arroz meloso con pollo y verduras en YouTube 🥘 Ya puedes verla en YouTube/RecetasConMari. ¡No olvides seguirme!', '2026-06-16 19:36:27', '2026-08-26 10:40:22');

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `jobs`
--

DROP TABLE IF EXISTS `jobs`;
CREATE TABLE IF NOT EXISTS `jobs` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `queue` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` smallint UNSIGNED NOT NULL,
  `reserved_at` int UNSIGNED DEFAULT NULL,
  `available_at` int UNSIGNED NOT NULL,
  `created_at` int UNSIGNED NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `job_batches`
--

DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE IF NOT EXISTS `job_batches` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_jobs` int NOT NULL,
  `pending_jobs` int NOT NULL,
  `failed_jobs` int NOT NULL,
  `failed_job_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cancelled_at` int DEFAULT NULL,
  `created_at` int NOT NULL,
  `finished_at` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `likes`
--

DROP TABLE IF EXISTS `likes`;
CREATE TABLE IF NOT EXISTS `likes` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint UNSIGNED DEFAULT NULL,
  `image_id` bigint UNSIGNED DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_likes_users` (`user_id`),
  KEY `fk_likes_images` (`image_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3617 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

