--
-- Estructura de tabla para la tabla `users`
--

DROP TABLE IF EXISTS `users`;
CREATE TABLE IF NOT EXISTS `users` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `role` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `surname` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nick` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `email` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `two_factor_secret` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `two_factor_recovery_codes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `two_factor_confirmed_at` timestamp NULL DEFAULT NULL,
  `remember_token` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_team_id` bigint UNSIGNED DEFAULT NULL,
  `profile_photo_path` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Volcado de datos para la tabla `users`
--

INSERT INTO `users` (`id`, `role`, `name`, `surname`, `nick`, `description`, `email`, `email_verified_at`, `password`, `image`, `two_factor_secret`, `two_factor_recovery_codes`, `two_factor_confirmed_at`, `remember_token`, `current_team_id`, `profile_photo_path`, `created_at`, `updated_at`) VALUES
(4, NULL, 'Juan Pablo Gutierrez Santorin', NULL, 'Jpablo87', 'Me pierdo por carreteras secundarias, pueblos pequeños y senderos que no salen en las guías. Café caliente, mochila ligera y ganas de descubrir qué hay detrás de la siguiente curva.', 'jpablo@aquim.com', NULL, '$2y$12$hkiwt3ItGsZC7o.5HSXJ7ep0McJCBecrdsgKUkYOS0UauLRRxVrma', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/CP58Bz3xds1pt26DBnwz0JfjRZEpGtSKkF2b6Ixu.jpg', '2026-07-05 11:36:27', '2026-08-23 13:04:47'),
(20, NULL, 'Laura garcia', NULL, '1LgarciaM', 'Viajo sin prisa, pruebo la comida de cada lugar y guardo los pequeños momentos que hacen especial cada escapada. Cuando estoy en casa, cambio la mochila por la cocina. 🌍🍝', 'lgarcia@aquim.com', NULL, '$2y$12$TwR11AWqZpEVkUnyrKwmVe8os.O1iL0F0bP3Q6v9ilDX/w37KxBXm', NULL, NULL, NULL, NULL, 'Z3Yu3zpBltwOhmkBzSYd3oZAKzPFbVHvPnG3m6PkjpbbjtskvWgGeMULj3kv', NULL, 'profile-photos/XSWtpa3Av3ySPRP8uxiOkg4W0JjPmVlBaQDS1WmS.png', '2026-08-22 09:18:28', '2026-08-28 12:46:36'),
(21, NULL, 'Sabor De Casa', NULL, 'SaborDeCasa', 'Recetas caseras nuevas cada semana 🍳 Platos fáciles, dulces y salados, explicados para que cualquiera pueda disfrutarlos en casa. ❤️', 'SaborDeCasa@aquim.com', NULL, '$2y$12$gdQgphD58/js52oRd/FsIe3QHHLPFwvGRtBzslODgPOMNLMcqj9Pq', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/Y2GsPzuhZpqpumIIRMKfbvgvE6soPGZJNYjsvb75.jpg', '2026-08-24 09:55:32', '2026-08-24 10:32:43'),
(23, NULL, 'Sara Garcia', NULL, 'SaraGarciaX', 'Creadora de contenido de maquillaje y moda ✨ Looks, pruebas de productos, eventos y un poco de mi día a día. Siempre buscando la próxima idea.', 'sgarcia@aquim.com', NULL, '$2y$12$X8AmqEY5JCghnzL.kZGfgeKy6c.vdlyN0HOv0MyJgFqpJlakaWPTK', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/JNPkcDiWOO7qgURRezWDAy8wak2rm39idA6N3Bub.jpg', '2026-08-24 16:53:19', '2026-08-24 17:42:43'),
(24, NULL, 'Mami de tres', NULL, 'MamiDe3', 'Mamá de tres, experta en sobrevivir a mañanas con prisas y tardes llenas de planes. Por aquí comparto nuestra vida real: juegos, escapadas, caos y muchísimo cariño. 👩‍👧‍👦', 'mamide3@aquim.com', NULL, '$2y$12$BCGC.hJZ3NlsDyUMifaeGONfPnPxXX37ObTJtU1zCC0z3jX1W3Vhy', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/DezxUDCxUSwAhh2RxezNBPZWJtANe4atI5cZmqoT.jpg', '2026-08-24 18:29:40', '2026-08-24 19:39:46'),
(25, NULL, 'Rory Ginger', NULL, 'Rory_23', 'Estudiante, consumidor habitual de café y especialista en dejar los trabajos para el último momento. Libros, paseos, trenes y cosas normales de cada día.', 'rory_23@aquim.com', NULL, '$2y$12$hkiwt3ItGsZC7o.5HSXJ7ep0McJCBecrdsgKUkYOS0UauLRRxVrma', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/7h60A1L0zz2VGLakoB5DpOKShbx58zDzY10aaN1x.png', '2026-08-24 19:47:51', '2026-08-25 08:44:58'),
(26, NULL, 'Lugares Espectaculares', NULL, 'LugaresEspectaculares', 'Una ventana a algunos de los lugares más espectaculares del planeta. 📍 Destino y país en cada publicación. 📸 Siempre acreditamos a quien está detrás de la cámara.', 'lugaresespectaculares@aquim.com', NULL, '$2y$12$hkiwt3ItGsZC7o.5HSXJ7ep0McJCBecrdsgKUkYOS0UauLRRxVrma', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/vYHxHiFyifR618aigHH4FWIi93D9X7bnCgesMuSu.png', '2026-08-25 05:02:37', '2026-08-25 08:25:01'),
(27, NULL, 'Jack Miller Frost', NULL, 'Explorandoconjack', 'Viajo para conocer los lugares de verdad, no solo para hacer la foto. Comparto ubicaciones, impresiones sinceras y consejos útiles para preparar cada aventura. 📍🌍', 'explorandoconjack@aquim.com', NULL, '$2y$12$/fZq.qgKQswSdhkQidKUMOYzJ3fKubhKH2ZC6jFYf1naLVYSJRNJ2', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/NB6ujZE8qJbo9ec4mJvUwk6oiwqNkvOXDL623SdB.png', '2026-08-25 17:11:37', '2026-08-25 18:17:48'),
(28, NULL, 'Maria', NULL, 'RecetasconMari', 'Recetas nuevas cada martes y viernes 🍽️ Vídeos completos, trucos sencillos y cocina para disfrutar sin complicaciones. Sígueme en YouTube/RecetasConMari.', 'recetasconmari@aquim.com', NULL, '$2y$12$xF4j8.6waKnSaNlmB6d94erohdT/8ShMP.ETtaj4gw92xzHnTEvXW', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/7Lu9zeJdn26yA6zlPPiz2cueWhOGfyircV1iHtJ1.png', '2026-08-25 17:14:37', '2026-08-25 18:10:16'),
(29, NULL, 'Axel Rios', NULL, 'Axel_Rios01', 'Modelo y apasionado del fitness. Pasarelas, sesiones, entrenamiento, running y comida sencilla para mantener el equilibrio dentro y fuera del gimnasio. 💪📸', 'axelrios01@aquim.com', NULL, '$2y$12$pXETlkWcQjTRAVB/wtwlJ.2EoLIGkYgUtNLxOxuJ38lvuKzq4P/ce', NULL, NULL, NULL, NULL, NULL, NULL, 'profile-photos/xY74MuxmMN8uX33h5XkE0PWep36psP0r6y4ppe5C.png', '2026-08-25 17:21:53', '2026-08-25 18:16:05'),
(30, NULL, 'Jon', NULL, 'jon01', 'Por aquí para descubrir ideas nuevas, guardar los lugares que me gustan y compartir algún momento de vez en cuando.', 'jon01@aquim.com', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-25 18:20:37', '2026-08-25 18:20:37'),
(31, NULL, 'Nicolás Ortega', NULL, 'NicoMontes', 'Montaña siempre que puedo ⛰️ Rutas de fin de semana, refugios, amaneceres fríos y algún camino equivocado que acaba convirtiéndose en la mejor parte.', 'NicoMontes@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-09 17:24:17', '2026-03-09 17:24:17'),
(32, NULL, 'Clara Campos', NULL, 'ClaraVisual', 'Fotografía por afición. Me gustan la luz natural, los detalles cotidianos y esas escenas que duran un segundo pero cuentan una historia entera. 📷', 'ClaraVisual@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-21 10:42:36', '2026-03-21 10:42:36'),
(33, NULL, 'Daniel Vega', NULL, 'DaniEnBici', 'Voy a casi todas partes en bici 🚲 Carreteras tranquilas, puertos, rutas improvisadas y el café que toca después de cada salida.', 'DaniEnBici@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-03 06:17:49', '2026-04-03 06:17:49'),
(34, NULL, 'Noa Serrano', NULL, 'NoaEntreLibros', 'Estudiante con más libros pendientes que tiempo libre. Leo entre clases, busco cafeterías tranquilas y nunca salgo de una librería con las manos vacías. 📚', 'NoaEntreLibros@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-16 18:05:28', '2026-04-16 18:05:28'),
(35, NULL, 'Marcos Luna', NULL, 'MarcosStreet', 'Calles, arquitectura y vida de barrio. Me gusta caminar sin rumbo y encontrar rincones interesantes donde parecía que no había nada.', 'MarcosStreet@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-28 11:36:54', '2026-04-28 11:36:54'),
(36, NULL, 'Elena Vidal', NULL, 'ElenaIlustra', 'Ilustradora, amante de los colores suaves y de llenar cuadernos con ideas a medio terminar. Aquí comparto bocetos, procesos y pequeños experimentos. 🎨', 'ElenaIlustra@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-10 15:52:11', '2026-05-10 15:52:11'),
(37, NULL, 'Hugo Martín', NULL, 'HugoTechLab', 'Tecnología, programación y proyectos que empiezan como una prueba rápida y terminan ocupando toda la mesa. Aprendiendo algo nuevo cada día. 💻', 'HugoTechLab@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-23 08:29:43', '2026-05-23 08:29:43'),
(38, NULL, 'Carla Ruiz', NULL, 'CarlaLooks', 'Moda para el día a día, combinaciones sencillas y prendas que realmente vuelvo a utilizar. Sin reglas complicadas: si me gusta y es cómodo, funciona. ✨', 'CarlaLooks@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-06-04 17:14:26', '2026-06-04 17:14:26'),
(39, NULL, 'Leo Navarro', NULL, 'LeoVinilos', 'Colecciono vinilos, entradas de conciertos y canciones para cada momento. Siempre buscando un disco nuevo que escuchar de principio a fin. 🎵', 'LeoVinilos@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-06-18 14:08:35', '2026-06-18 14:08:35'),
(40, NULL, 'Marta Soler', NULL, 'MartaVerde', 'Mi casa está llena de plantas y siempre cabe una más 🌿 Comparto cuidados sencillos, pequeños avances y algún rescate vegetal que no siempre sale bien.', 'MartaVerde@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-01 07:47:52', '2026-07-01 07:47:52'),
(41, NULL, 'Adrián Peña', NULL, 'AdrianAlPlato', 'Me gusta probar sitios nuevos y contar qué merece realmente la pena pedir. Desde el bar del barrio hasta ese restaurante reservado para una ocasión especial. 🍽️', 'AdrianAlPlato@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-13 19:03:19', '2026-07-13 19:03:19'),
(42, NULL, 'Irene Gil', NULL, 'IreneDeCine', 'Veo demasiadas películas y luego necesito comentarlas. Cine, series, bandas sonoras y recomendaciones sin destripar el final. 🎬', 'IreneDeCine@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26 16:31:44', '2026-07-26 16:31:44'),
(43, NULL, 'Pablo Blanco', NULL, 'PabloMotor', 'Coches clásicos, rutas de domingo y mecánica aprendida a base de paciencia. Me interesa más la historia de cada coche que presumir de cifras. 🚗', 'PabloMotor@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-08 10:56:07', '2026-08-08 10:56:07'),
(44, NULL, 'Lucía Torres', NULL, 'LuciaConNala', 'La vida con Nala: paseos largos, pelos por toda la casa y la certeza de que ella manda. También comparto ideas y lugares donde los perros son bienvenidos. 🐾', 'LuciaConNala@aquim', NULL, '$2y$12$mvFKbu4gYye44FjfMCqFiuFmiqC/eXGfjDHt..1f8/cCMFRj4WChC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-20 13:22:38', '2026-08-20 13:22:38');

